SELECT e.event_id, m.case_id, e.activity, e.timestamp FROM (SELECT * FROM (SELECT 'TX:' || t.transaction_id event_id, t.warehouse_number case_id, 'Goods Received' activity, t.occurred_at timestamp FROM transaction_record t WHERE t.transaction_type='IN' UNION ALL SELECT 'TX:' || t.transaction_id event_id, t.warehouse_number case_id, 'Goods Dispatched' activity, t.occurred_at timestamp FROM transaction_record t WHERE t.transaction_type='OUT')) e JOIN (SELECT 'TX:' || transaction_id event_id, goods_id case_id FROM goods_transaction_detail) m ON m.event_id=e.event_id ORDER BY m.case_id,e.timestamp,e.event_id;
